/*
 * NETWORK_$REQUEST_SERVER - The network request server process
 *
 * Original address: 0x00E118DC (SAU2 map: NETWORK, NETWORK_$REQUEST_SERVER
 * at E118DC)
 * Size: 1418 bytes (0x00E118DC .. 0x00E11E6F); its send-options word
 * follows at 0x00E11E70.
 * Generated by: Claude Opus 5.5
 *
 * The body of the request server process (NETWORK_$ADD_REQUEST_SERVERS
 * hands its address to PROC1_$CREATE_P, DATA xref 0x00E71E4A).  After
 * enlarging the remote page pool and opening sockets 2 (file), 4
 * (asknode) and 8 (RIP) it waits forever on five eventcounts and serves
 * whichever advanced:
 *
 *   0 socket 2  REM_FILE_$SERVER                         (0x00E11AC2)
 *   1 socket 4  ASKNODE_$SERVER; a WHO request is propagated after the
 *               delay ASKNODE_$SERVER leaves in the context record, by
 *               switching this slot to a private eventcount advanced by
 *               TIME_$ADVANCE                              (0x00E11AE6)
 *   2 socket 8  RIP_$SERVER                               (0x00E11BA8)
 *   3 the clock RIP_$AGE every tick; every 4th minute boundary
 *               (ticks % 240 / 60 == 0), when a ring is present, send a
 *               null packet to this node's ring and report a ring failure
 *               if three sends fail                      (0x00E11BCC)
 *   4 NETWORK_$RQST_QUIT_EC  unbind and crash (the server is dismissed)
 *                                                          (0x00E11DE0)
 *
 * and then (0x00E11E2E) looks for a later slot that is also satisfied
 * before waiting again.  The jump table at 0x00E11AB8 is
 * 00 0a 00 2e 00 f0 01 14 03 28.
 *
 * Frame (link.w A6,-0xe0; D2-D7/A2/A3/A5 saved; A5 = 0xE248FC):
 *   (-0x20,A6)  elem       time_queue_elem_t; its +8 (A6-0x18) is tested
 *                          before TIME_$CANCEL, its +0x12 (A6-0xE) cleared
 *   (-0x40,A6)  pkt_info   NETWORK_$SERVER_PKT_INFO copy (0x1E bytes)
 *   (-0x50,A6)  wait_ec    the private eventcount for delayed WHO
 *   (-0x78,A6)  ctx        asknode_$server_ctx_t (its clock at A6-0x5C)
 *   (-0x90,A6)  waits[5]   (-0xA8,A6) ecs[5]   (-0xAC,A6) port
 *   (-0xB0,A6)  routing    (-0xB4,A6) status
 *   (-0xB8,A6)  hdr_pa     (-0xC0,A6) hdr_va   (-0xC6,A6) timeout
 *   (-0xC8,A6)  retry      (-0xD0,A6) result   (-0xD2,A6) out_port
 *   (-0xD4,A6)  hdr_len    (-0xDA,A6) the spin-lock token
 *   D2w the ring error total at the last check, D3w the slot.
 *
 * Quirks reproduced:
 *   - The PKT_$BLD_INTERNET_HDR / RING_$SENDP data pointers are the zero
 *     longword at 0x00E1050C (network_$c_zero_long), which RING_$SENDP is
 *     documented to copy four longwords from.
 *   - The quit arm calls CRASH_SYSTEM with PROC1_$UNBIND's status and then
 *     falls into the scan as if it returned.
 */

#include "network/network_internal.h"
#include "asknode/asknode.h"
#include "rem_file/rem_file.h"
#include "rip/rip.h"
#include "app/app.h"
#include "ring/ring.h"
#include "route/route.h"
#include "time/time.h"
#include "node/node.h"
#include "misc/crash_system.h"

/* Sockets the server opens (0x00E11954-0x00E1199E) */
#define NETWORK_RQST_SOCK_FILE      2
#define NETWORK_RQST_SOCK_ASKNODE   4
#define NETWORK_RQST_SOCK_RIP       8

/* The context magic: `move.w #-0x2151,(-0x78,A6)` = 0xDEAF */
#define NETWORK_RQST_CTX_UNTOUCHED  ((uint16_t)0xDEAF)

/* Clock slot period in ticks: `moveq #0x3c` */
#define NETWORK_RQST_CLOCK_TICKS    0x3C

/* Ring failure check window: `cmpi.l #0x157,D1` at 0x00E11C80 */
#define NETWORK_RQST_FAILURE_WINDOW 0x157

/* The ring null packet: socket 4 of "node" 4 */
#define NETWORK_RQST_NULL_NODE      4

/* RING_$SENDP result bits that mean "not delivered" (0x00E11D62-0x00E11D72) */
#define NETWORK_RQST_XMIT_FAIL_A    0x0020
#define NETWORK_RQST_XMIT_FAIL_B    0x0400

/*
 * By-reference constants.  0x00E0F744 (00 00) is TIME_$ADVANCE's "relative"
 * flag (`pea (-0x2416,PC)` at 0x00E11B58); 0x00E11E70 (00 00) is
 * RING_$SENDP's send-options word (`pea (0x140,PC)` at 0x00E11D2E).
 */
static const uint16_t network_$rqst_relative = 0;       /* 0x00E0F744 */
static const uint16_t network_$rqst_send_opts = 0;      /* 0x00E11E70 */

/*
 * The clock slot's next wait value, repeated at 0x00E119EE, 0x00E11BFC and
 * 0x00E11DA8: one period past the later of itself and the clock.
 */
static uint32_t network_$rqst_next_tick(void)
{
    uint32_t cur = NETWORK_$RQST_WAIT[3];

    if ((int32_t)NETWORK_$RQST_WAIT[3] < (int32_t)TIME_$CLOCKH) {
        NETWORK_$RQST_WAIT[3] = TIME_$CLOCKH + NETWORK_RQST_CLOCK_TICKS;
    } else {
        NETWORK_$RQST_WAIT[3] += NETWORK_RQST_CLOCK_TICKS;
    }
    return cur;
}

void NETWORK_$REQUEST_SERVER(void)
{
    time_queue_elem_t elem;            /* (-0x20,A6) */
    pkt_$info_t pkt_info;              /* (-0x40,A6) */
    ec_$eventcount_t wait_ec;          /* (-0x50,A6) */
    asknode_$server_ctx_t ctx;         /* (-0x78,A6) */
    uint32_t waits[5];                 /* (-0x90,A6) */
    ec_$eventcount_t *ecs[5];          /* (-0xA8,A6) */
    route_$port_t *port;               /* (-0xAC,A6) */
    int32_t routing;                   /* (-0xB0,A6) */
    status_$t status;                  /* (-0xB4,A6) */
    uint32_t hdr_pa;                   /* (-0xB8,A6) */
    uint32_t hdr_va;                   /* (-0xC0,A6) */
    uint16_t timeout;                  /* (-0xC6,A6) */
    uint16_t retry;                    /* (-0xC8,A6) */
    uint16_t result;                   /* (-0xD0,A6) */
    int16_t out_port;                  /* (-0xD2,A6) */
    uint16_t hdr_len;                  /* (-0xD4,A6) */
    ml_$spin_token_t token;            /* (-0xDA,A6) */
    uint16_t last_errors;              /* D2w */
    uint16_t errors;                   /* D1w */
    int16_t delta;                     /* D0w */
    int16_t slot;                      /* D3w */
    int16_t k, n;                      /* D4w, D3w */
    int16_t tries;                     /* D4w */
    int8_t report;                     /* D6b */
    int8_t saved;                      /* D5b */
    uint32_t hdr;                      /* A2 */
    const uint8_t *src;
    uint8_t *dst;
    int i;

    /* 0x00E118EA-0x00E118F8 */
    src = (const uint8_t *)&NETWORK_$SERVER_PKT_INFO;
    dst = (uint8_t *)&pkt_info;
    for (i = 0; i < NETWORK_SERVER_PKT_INFO_LEN; i++) {
        dst[i] = src[i];
    }

    /* 0x00E118FA-0x00E11950: one more page for the remote pool */
    token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
    MMAP_$MIN_RMT_POOL += 1;
    MMAP_$PAGEABLE_PAGES_LOWER_LIMIT = MMAP_$MIN_RMT_POOL;
    ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);
    if ((int32_t)MMAP_$RMT_LIMIT < 0 &&
        (int32_t)NETWORK_$REMOTE_POOL < (int32_t)MMAP_$MIN_RMT_POOL) {
        NETWORK_$SET_REMOTE_POOL(MMAP_$REMOTE_POOL(MMAP_$MIN_RMT_POOL));
    }

    /* 0x00E11952-0x00E119B4 */
    SOCK_$OPEN(NETWORK_RQST_SOCK_FILE, 0x100000, 0x10400);
    SOCK_$OPEN(NETWORK_RQST_SOCK_ASKNODE, 0x80000, 0x400);
    SOCK_$OPEN(NETWORK_RQST_SOCK_RIP, 0x40000, 0x400);
    if (NETWORK_$STD_OPEN_FLAG < 0) {
        RIP_$STD_OPEN();
        APP_$STD_OPEN();
        NETWORK_$STD_OPEN_FLAG = 0;
    }

    /* 0x00E119B8-0x00E11A28 */
    elem.callback_arg = 0;
    elem.flags = 0;
    token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
    waits[0] = NETWORK_$RQST_WAIT[0]++;
    waits[1] = NETWORK_$RQST_WAIT[1]++;
    waits[2] = NETWORK_$RQST_WAIT[2]++;
    waits[3] = network_$rqst_next_tick();
    waits[4] = 1;
    ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);

    /* 0x00E11A2A-0x00E11A86 */
    ecs[0] = &SOCK_$DATA.socket_ptr[NETWORK_RQST_SOCK_FILE]->ec;
    ecs[1] = &SOCK_$DATA.socket_ptr[NETWORK_RQST_SOCK_ASKNODE]->ec;
    ecs[2] = &SOCK_$DATA.socket_ptr[NETWORK_RQST_SOCK_RIP]->ec;
    ecs[3] = (ec_$eventcount_t *)&TIME_$CLOCKH;
    ecs[4] = &NETWORK_$RQST_QUIT_EC;
    EC_$INIT(&wait_ec);
    last_errors = 0;
    if (ROUTE_$PORT_ARRAY[0].port_type == 0) {
        port = ROUTE_$WIRED_DATA.portp[0];
    } else {
        port = NULL;
    }
    PROC1_$INHIBIT_BEGIN();
    ML_$EXCLUSION_INIT(&REM_FILE_$SOCK_LOCK);

    for (;;) {
        /* 0x00E11A88-0x00E11AA2 */
        slot = (int16_t)(EC_$WAITN(ecs, (int32_t *)waits, 5) - 1);

    dispatch:
        switch (slot) {
        case 0:
            /* 0x00E11AC2-0x00E11AE2 */
            REM_FILE_$SERVER();
            token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
            waits[0] = NETWORK_$RQST_WAIT[0]++;
            ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);
            break;

        case 1:
            /* 0x00E11AE6-0x00E11BA6 */
            if ((void *)ecs[1] == (void *)SOCK_$DATA.socket_ptr[NETWORK_RQST_SOCK_ASKNODE]) {
                ctx.version = NETWORK_RQST_CTX_UNTOUCHED;
                ctx.clock_hi = 0;
                ctx.clock_lo = 0;
                ASKNODE_$SERVER(&ctx, &routing);
                if (ctx.version != NETWORK_RQST_CTX_UNTOUCHED) {
                    /* 0x00E11B1A-0x00E11B6C: propagate it later */
                    ecs[1] = &wait_ec;
                    waits[1] = (uint32_t)(wait_ec.value + 1);
                    if (elem.callback_arg != 0) {
                        TIME_$CANCEL(wait_ec.value, &elem, &status);
                    }
                    TIME_$ADVANCE((uint16_t *)&network_$rqst_relative,
                                  (clock_t *)(void *)((uint8_t *)&ctx + 0x1C),
                                  &wait_ec, &elem, &status);
                    if (status == status_$ok) {
                        break;                               /* to the scan */
                    }
                    goto propagate;
                }
            } else {
            propagate:
                /* 0x00E11B8E-0x00E11BA6 */
                ASKNODE_$PROPAGATE_WHO((int16_t *)(void *)&ctx, (uint32_t *)&routing);
                ecs[1] = &SOCK_$DATA.socket_ptr[NETWORK_RQST_SOCK_ASKNODE]->ec;
            }
            /* 0x00E11B70-0x00E11B8A */
            token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
            waits[1] = NETWORK_$RQST_WAIT[1]++;
            ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);
            break;

        case 2:
            /* 0x00E11BA8-0x00E11BC8 */
            RIP_$SERVER();
            token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
            waits[2] = NETWORK_$RQST_WAIT[2]++;
            ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);
            break;

        case 3:
            /* 0x00E11BCC-0x00E11C32 */
            RIP_$AGE();
            token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
            NETWORK_$AGE_TICKS++;
            if ((int16_t)((int16_t)NETWORK_$AGE_TICKS % 0xF0) / 0x3C != 0) {
                waits[3] = network_$rqst_next_tick();
                ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);
                continue;                                    /* 0x00E11C32 */
            }
            ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);

            /* 0x00E11C46-0x00E11D94: the ring check */
            if (NETWORK_$RING_DCTE != 0 && port != NULL && port->active != 1) {
                errors = (uint16_t)(RING_$WIRED_DATA.stats[0].xmit_modem +
                                    RING_$WIRED_DATA.stats[0].xmit_nortn);
                delta = (int16_t)(errors - last_errors);
                last_errors = errors;
                if ((int32_t)(TIME_$CLOCKH - NETWORK_$FAILURE_REC.timestamp) <
                    NETWORK_RQST_FAILURE_WINDOW) {
                    report = (NETWORK_$FAILURE_REC.node_id == NODE_$ME) ? (int8_t)0xFF : 0;
                } else {
                    report = (int8_t)(~(uint8_t)NETWORK_$ACTIVITY_FLAG |
                                      (delta > 0 ? 0xFF : 0));
                }
                saved = (int8_t)(~(uint8_t)report & (uint8_t)NETWORK_$FAILURE_REC.flag);
                if (report < 0) {
                    tries = 2;
                    do {
                        /* 0x00E11CB2-0x00E11D72 */
                        NETWORK_$GETHDR((uint32_t *)&network_$c_zero_long,
                                        &hdr_va, &hdr_pa);
                        pkt_info.flags = 0;
                        hdr = hdr_va;
                        PKT_$BLD_INTERNET_HDR(0, NETWORK_RQST_NULL_NODE, 0, 0,
                                              NODE_$ME, 0, &pkt_info, 0,
                                              (void *)&network_$c_zero_long,
                                              0, 0, &out_port,
                                              (pkt_$hdr_t *)ARCH_VA_TO_PTR(hdr),
                                              &hdr_len, &retry, &timeout,
                                              &status);
                        hdr_va = hdr;
                        if (status != status_$ok) {
                            CRASH_SYSTEM(&status);
                        }
                        RING_$SENDP(&port->socket, hdr_pa,
                                    (ring_$pkt_hdr_t *)ARCH_VA_TO_PTR(hdr_va),
                                    hdr_len, &network_$c_zero_long, 0, 0,
                                    &network_$rqst_send_opts, &result, &status);
                        NETWORK_$RTNHDR(&hdr_va);
                        if ((result & NETWORK_RQST_XMIT_FAIL_A) == 0 &&
                            (result & NETWORK_RQST_XMIT_FAIL_B) == 0) {
                            report = 0;
                            break;
                        }
                    } while (--tries != -1);
                    if (report < 0) {
                        NETWORK_$REPORT_FAILURE(&result);    /* 0x00E11D84 */
                        goto clear_activity;
                    }
                }
                NETWORK_$FAILURE_REC.flag = saved;           /* 0x00E11D90 */
            clear_activity:
                NETWORK_$ACTIVITY_FLAG = 0;                  /* 0x00E11D94 */
            }

            /* 0x00E11D98-0x00E11DDE */
            token = ML_$SPIN_LOCK(&NETWORK_$LOCK);
            waits[3] = network_$rqst_next_tick();
            ML_$SPIN_UNLOCK(&NETWORK_$LOCK, token);
            break;

        case 4:
            /* 0x00E11DE0-0x00E11E2C: dismissed */
            if (elem.callback_arg != 0) {
                TIME_$CANCEL(wait_ec.value, &elem, &status);
            }
            PROC1_$INHIBIT_END();
            EC_$ADVANCE(&NETWORK_$RQST_DONE_EC);
            PROC1_$UNBIND(PROC1_$CURRENT, &status);
            CRASH_SYSTEM(&status);
            break;

        default:
            break;
        }

        /* 0x00E11E2E-0x00E11E6C: serve a later slot that is also ready */
        k = (int16_t)(slot + 1);
        n = (int16_t)(4 - k);
        if (n < 0) {
            continue;
        }
        do {
            if ((int32_t)(EC_$READ(ecs[k]) - (int32_t)waits[k]) >= 0) {
                slot = k;
                goto dispatch;
            }
            k++;
        } while (--n != -1);
    }
}
